65: /* The eye is off the axis, at (3, 0, 4) looking at the origin, because from
66:  * the axis the rotation is the identity and a transposed matrix would look
67:  * the same. By hand with a 90 degree field of view: the world point (1, 0, 0)
68:  * is 4.4 in front of the eye and 0.8 to its right, so ndc x = 0.8 / 4.4 =
69:  * 0.18, pixel column 37.8 of 64. The triangle below projects to a shape that
70:  * covers row 32 from about column 36 to 39.7. Red, not white, so a byte swap
71:  * would show. */
72: void test_perspective_and_lookat_put_a_point_where_the_maths_says(void) {
73:   TEST_ASSERT_NOT_NULL(glshim_open(&cv));
74:   glViewport(0, 0, SIZE, SIZE);
75:   glMatrixMode(GL_PROJECTION);
76:   glLoadIdentity();
77:   gluPerspective(90, 1, 1, 100);
78:   glMatrixMode(GL_MODELVIEW);
79:   glLoadIdentity();
80:   gluLookAt(3, 0, 4, 0, 0, 0, 0, 1, 0);
81:   glDisable(GL_LIGHTING);
82:   glColor3f(1, 0, 0);
83:   glBegin(GL_TRIANGLES);
84:   glVertex3f(0.5f, -0.6f, 0.0f);
85:   glVertex3f(1.5f, -0.6f, 0.0f);
86:   glVertex3f(1.0f, 0.6f, 0.0f);
87:   glEnd();
88:   TEST_ASSERT_EQUAL_HEX16(rgb565(255, 0, 0), cv.px[32 * SIZE + 37]);
89:   TEST_ASSERT_EQUAL_HEX16(0, cv.px[32 * SIZE + 16]);
90: }
