92: /* TinyGL lights a vertex with specular only if glSetEnableSpecular(1) is on
93:  * (it is off by default, and the hacks here never switch it on, so Gears has
94:  * no highlights). With it on, a vertex whose normal is (1, 0, 0) under a
95:  * light in direction (0.6, 0, 0.8) gets specular 0.6 ^ shininess: bright at
96:  * shininess 1, black at 100. If glMateriali did not reach TinyGL the
97:  * shininess would stay 0, and 0.6 ^ 0 is 1: bright in both. */
98: static int specular_red_at_centre(int shininess) {
99:   TEST_ASSERT_NOT_NULL(glshim_open(&cv));
100:   glViewport(0, 0, SIZE, SIZE);
101:   glMatrixMode(GL_PROJECTION);
102:   glLoadIdentity();
103:   glMatrixMode(GL_MODELVIEW);
104:   glLoadIdentity();
105:   const GLfloat black[4] = {0, 0, 0, 1}, white[4] = {1, 1, 1, 1};
106:   const GLfloat direction[4] = {0.6f, 0, 0.8f, 0};
107:   glEnable(GL_LIGHTING);
108:   glEnable(GL_LIGHT0);
109:   glSetEnableSpecular(1);
110:   glLightfv(GL_LIGHT0, GL_POSITION, (GLfloat *)direction);
111:   glLightfv(GL_LIGHT0, GL_AMBIENT, (GLfloat *)black);
112:   glLightfv(GL_LIGHT0, GL_DIFFUSE, (GLfloat *)black);
113:   glLightfv(GL_LIGHT0, GL_SPECULAR, (GLfloat *)white);
114:   glLightModelfv(GL_LIGHT_MODEL_AMBIENT, (GLfloat *)black);
115:   glMaterialfv(GL_FRONT_AND_BACK, GL_AMBIENT, (GLfloat *)black);
116:   glMaterialfv(GL_FRONT_AND_BACK, GL_DIFFUSE, (GLfloat *)black);
117:   glMaterialfv(GL_FRONT_AND_BACK, GL_SPECULAR, (GLfloat *)white);
118:   glMateriali(GL_FRONT_AND_BACK, GL_SHININESS, shininess);
119:   glNormal3f(1, 0, 0);
120:   glBegin(GL_TRIANGLES);
121:   glVertex3f(-0.9f, -0.9f, 0);
122:   glVertex3f(0.9f, -0.9f, 0);
123:   glVertex3f(0.0f, 0.9f, 0);
124:   glEnd();
125:   return px_swap(cv.px[(SIZE / 2) * SIZE + SIZE / 2]) >> 11; /* red, 0 to 31 */
126: }
127: 
128: void test_materiali_sets_the_shininess_tinygl_uses(void) {
129:   TEST_ASSERT_TRUE(specular_red_at_centre(1) >= 12);
130:   TEST_ASSERT_TRUE(specular_red_at_centre(100) <= 1);
131: }
