172: /* Vertex arrays, as tube.c and sphere.c build them: one interleaved struct per
173:  * vertex, a stride in bytes, freed straight after the draw. */
174: typedef struct {
175:   float n[3];
176:   float v[3];
177:   float pad[2];
178: } Vtx; /* 32 bytes */
179: 
180: static const Vtx kTri[3] = {{{0, 0, 1}, {-0.8f, -0.8f, 0}, {0, 0}},
181:                             {{0, 0, 1}, {0.8f, -0.8f, 0}, {0, 0}},
182:                             {{0, 0, 1}, {0.0f, 0.8f, 0}, {0, 0}}};
183: 
184: static uint16_t reference[SIZE * SIZE];
185: 
186: static void open_flat_red_scene(void) {
187:   TEST_ASSERT_NOT_NULL(glshim_open(&cv));
188:   glViewport(0, 0, SIZE, SIZE);
189:   glMatrixMode(GL_PROJECTION);
190:   glLoadIdentity();
191:   glMatrixMode(GL_MODELVIEW);
192:   glLoadIdentity();
193:   glDisable(GL_LIGHTING);
194:   glColor3f(1, 0, 0);
195:   glDisableClientState(GL_VERTEX_ARRAY);
196:   glDisableClientState(GL_NORMAL_ARRAY);
197: }
198: 
199: static void draw_triangle_immediately(void) {
200:   glBegin(GL_TRIANGLES);
201:   for (int i = 0; i < 3; i++) glVertex3f(kTri[i].v[0], kTri[i].v[1], kTri[i].v[2]);
202:   glEnd();
203: }
204: 
205: static void take_reference_and_clear(void) {
206:   draw_triangle_immediately();
207:   memcpy(reference, cv.px, sizeof reference);
208:   glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
209: }
210: 
211: static int count_set(void) {
212:   int n = 0;
213:   for (int i = 0; i < SIZE * SIZE; i++) n += cv.px[i] != 0;
214:   return n;
215: }
216: 
217: static void point_at(const Vtx *tri) {
218:   glVertexPointer(3, GL_FLOAT, sizeof(Vtx), &tri->v);
219:   glNormalPointer(GL_FLOAT, sizeof(Vtx), &tri->n);
220:   glEnableClientState(GL_VERTEX_ARRAY);
221:   glEnableClientState(GL_NORMAL_ARRAY);
222: }
223: 
224: void test_draw_arrays_honours_a_byte_stride(void) {
225:   open_flat_red_scene();
226:   take_reference_and_clear();
227:   point_at(kTri);
228:   glDrawArrays(GL_TRIANGLES, 0, 3);
229:   TEST_ASSERT_TRUE(count_set() > 100);
230:   TEST_ASSERT_EQUAL_MEMORY(reference, cv.px, sizeof reference);
231: }
232: 
233: /* This is the bug that drew needles: TinyGL read the array when the list was
234:  * replayed, after the hack had freed it. */
235: void test_a_display_list_keeps_the_arrays_it_recorded(void) {
236:   open_flat_red_scene();
237:   take_reference_and_clear();
238:   Vtx *tri = malloc(sizeof kTri);
239:   memcpy(tri, kTri, sizeof kTri);
240:   point_at(tri);
241:   const GLuint list = glGenLists(1);
242:   glNewList(list, GL_COMPILE);
243:   glDrawArrays(GL_TRIANGLES, 0, 3);
244:   glEndList();
245:   memset(tri, 0xFF, sizeof kTri);
246:   free(tri);
247:   glCallList(list);
248:   TEST_ASSERT_TRUE(count_set() > 100);
249:   TEST_ASSERT_EQUAL_MEMORY(reference, cv.px, sizeof reference);
250: }
