252: /* A new context starts with every client array disabled; the arrays the last
253:  * hack left enabled point at memory it has freed. */
254: void test_a_new_context_starts_with_no_client_arrays_enabled(void) {
255:   open_flat_red_scene();
256:   point_at(kTri);
257:   glshim_close();
258:   TEST_ASSERT_NOT_NULL(glshim_open(&cv));
259:   glViewport(0, 0, SIZE, SIZE);
260:   glMatrixMode(GL_PROJECTION);
261:   glLoadIdentity();
262:   glMatrixMode(GL_MODELVIEW);
263:   glLoadIdentity();
264:   glDisable(GL_LIGHTING);
265:   glColor3f(1, 0, 0);
266:   glDrawArrays(GL_TRIANGLES, 0, 3);
267:   TEST_ASSERT_EQUAL_INT(0, count_set());
268: }
269: 
270: void test_draw_arrays_with_nothing_enabled_or_a_zero_count_draws_nothing(void) {
271:   open_flat_red_scene();
272:   glVertexPointer(3, GL_FLOAT, sizeof(Vtx), &kTri[0].v);
273:   glDrawArrays(GL_TRIANGLES, 0, 3); /* pointers set, nothing enabled */
274:   TEST_ASSERT_EQUAL_INT(0, count_set());
275:   glEnableClientState(GL_VERTEX_ARRAY);
276:   glDrawArrays(GL_TRIANGLES, 0, 0);
277:   TEST_ASSERT_EQUAL_INT(0, count_set());
278: }
