172: /* Vertex arrays, as tube.c and sphere.c build them: one interleaved struct per
173:  * vertex, a stride in bytes, freed straight after the draw. */
174: typedef struct {
175:   float n[3];
176:   float v[3];
177:   float pad[2];
178: } Vtx; /* 32 bytes */
179: 
180: static const Vtx kTri[3] = {{{0, 0, 1}, {-0.8f, -0.8f, 0}, {0, 0}},
181:                             {{0, 0, 1}, {0.8f, -0.8f, 0}, {0, 0}},
182:                             {{0, 0, 1}, {0.0f, 0.8f, 0}, {0, 0}}};
183: 
184: static uint16_t reference[SIZE * SIZE];
185: 
186: static void open_flat_red_scene(void) {
187:   TEST_ASSERT_NOT_NULL(glshim_open(&cv));
188:   glViewport(0, 0, SIZE, SIZE);
189:   glMatrixMode(GL_PROJECTION);
190:   glLoadIdentity();
191:   glMatrixMode(GL_MODELVIEW);
192:   glLoadIdentity();
193:   glDisable(GL_LIGHTING);
194:   glColor3f(1, 0, 0);
195:   glDisableClientState(GL_VERTEX_ARRAY);
196:   glDisableClientState(GL_NORMAL_ARRAY);
197: }
198: 
199: static void draw_triangle_immediately(void) {
200:   glBegin(GL_TRIANGLES);
201:   for (int i = 0; i < 3; i++) glVertex3f(kTri[i].v[0], kTri[i].v[1], kTri[i].v[2]);
202:   glEnd();
203: }
204: 
205: static void take_reference_and_clear(void) {
206:   draw_triangle_immediately();
207:   memcpy(reference, cv.px, sizeof reference);
208:   glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
209: }
210: 
211: static int count_set(void) {
212:   int n = 0;
213:   for (int i = 0; i < SIZE * SIZE; i++) n += cv.px[i] != 0;
214:   return n;
215: }
216: 
217: static void point_at(const Vtx *tri) {
218:   glVertexPointer(3, GL_FLOAT, sizeof(Vtx), &tri->v);
219:   glNormalPointer(GL_FLOAT, sizeof(Vtx), &tri->n);
220:   glEnableClientState(GL_VERTEX_ARRAY);
221:   glEnableClientState(GL_NORMAL_ARRAY);
222: }
223: 
224: void test_draw_arrays_honours_a_byte_stride(void) {
225:   open_flat_red_scene();
226:   take_reference_and_clear();
227:   point_at(kTri);
228:   glDrawArrays(GL_TRIANGLES, 0, 3);
229:   TEST_ASSERT_TRUE(count_set() > 100);
230:   TEST_ASSERT_EQUAL_MEMORY(reference, cv.px, sizeof reference);
231: }
232: 
233: /* This is the bug that drew needles: TinyGL read the array when the list was
234:  * replayed, after the hack had freed it. */
235: void test_a_display_list_keeps_the_arrays_it_recorded(void) {
236:   open_flat_red_scene();
237:   take_reference_and_clear();
238:   Vtx *tri = malloc(sizeof kTri);
239:   memcpy(tri, kTri, sizeof kTri);
240:   point_at(tri);
241:   const GLuint list = glGenLists(1);
242:   glNewList(list, GL_COMPILE);
243:   glDrawArrays(GL_TRIANGLES, 0, 3);
244:   glEndList();
245:   memset(tri, 0xFF, sizeof kTri);
246:   free(tri);
247:   glCallList(list);
248:   TEST_ASSERT_TRUE(count_set() > 100);
249:   TEST_ASSERT_EQUAL_MEMORY(reference, cv.px, sizeof reference);
250: }
251: 
252: /* A new context starts with every client array disabled; the arrays the last
253:  * hack left enabled point at memory it has freed. */
254: void test_a_new_context_starts_with_no_client_arrays_enabled(void) {
255:   open_flat_red_scene();
256:   point_at(kTri);
257:   glshim_close();
258:   TEST_ASSERT_NOT_NULL(glshim_open(&cv));
259:   glViewport(0, 0, SIZE, SIZE);
260:   glMatrixMode(GL_PROJECTION);
261:   glLoadIdentity();
262:   glMatrixMode(GL_MODELVIEW);
263:   glLoadIdentity();
264:   glDisable(GL_LIGHTING);
265:   glColor3f(1, 0, 0);
266:   glDrawArrays(GL_TRIANGLES, 0, 3);
267:   TEST_ASSERT_EQUAL_INT(0, count_set());
268: }
269: 
270: void test_draw_arrays_with_nothing_enabled_or_a_zero_count_draws_nothing(void) {
271:   open_flat_red_scene();
272:   glVertexPointer(3, GL_FLOAT, sizeof(Vtx), &kTri[0].v);
273:   glDrawArrays(GL_TRIANGLES, 0, 3); /* pointers set, nothing enabled */
274:   TEST_ASSERT_EQUAL_INT(0, count_set());
275:   glEnableClientState(GL_VERTEX_ARRAY);
276:   glDrawArrays(GL_TRIANGLES, 0, 0);
277:   TEST_ASSERT_EQUAL_INT(0, count_set());
278: }
279: 
280: int main(void) {
281:   UNITY_BEGIN();
282:   RUN_TEST(test_draw_arrays_honours_a_byte_stride);
283:   RUN_TEST(test_a_display_list_keeps_the_arrays_it_recorded);
284:   RUN_TEST(test_a_new_context_starts_with_no_client_arrays_enabled);
285:   RUN_TEST(test_draw_arrays_with_nothing_enabled_or_a_zero_count_draws_nothing);
286:   RUN_TEST(test_clear_writes_canvas_byte_order);
287:   RUN_TEST(test_the_first_list_name_is_not_zero);
288:   RUN_TEST(test_perspective_and_lookat_put_a_point_where_the_maths_says);
289:   RUN_TEST(test_materiali_sets_the_shininess_tinygl_uses);
290:   RUN_TEST(test_is_enabled_reports_texturing_off);
291:   RUN_TEST(test_swap_buffers_marks_every_row_dirty);
292:   RUN_TEST(test_releasing_the_display_frees_the_context);
293:   RUN_TEST(test_opening_twice_replaces_the_context_without_leaking);
294:   RUN_TEST(test_opening_on_an_empty_canvas_returns_null);
295:   return UNITY_END();
296: }

